describe('Total Price Update on Quantity Change', () => {
  beforeEach(() => {
    cy.visit('/cart');
    cy.get('[data-testid="cart-item"]').should('exist');
  });

  it('should update total price when quantity is increased', () => {
    cy.get('[data-testid="item-price"]').first().then(($price) => {
      const initialPrice = parseFloat($price.text().replace('$', ''));

      cy.get('[data-testid="quantity-input"]').first().clear().type('2');
      cy.get('[data-testid="update-quantity-btn"]').first().click();

      cy.get('[data-testid="total-price"]').should(($total) => {
        const totalPrice = parseFloat($total.text().replace('$', ''));
        expect(totalPrice).to.equal(initialPrice * 2);
      });
    });
  });

  it('should update total price when quantity is decreased', () => {
    cy.get('[data-testid="item-price"]').first().then(($price) => {
      const initialPrice = parseFloat($price.text().replace('$', ''));

      cy.get('[data-testid="quantity-input"]').first().clear().type('3');
      cy.get('[data-testid="update-quantity-btn"]').first().click();
      cy.wait(500);

      cy.get('[data-testid="quantity-input"]').first().clear().type('1');
      cy.get('[data-testid="update-quantity-btn"]').first().click();

      cy.get('[data-testid="total-price"]').should(($total) => {
        const totalPrice = parseFloat($total.text().replace('$', ''));
        expect(totalPrice).to.equal(initialPrice);
      });
    });
  });

  it('should handle edge case of zero quantity gracefully', () => {
    cy.get('[data-testid="quantity-input"]').first().clear().type('0');
    cy.get('[data-testid="update-quantity-btn"]').first().click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Quantity must be at least 1');
  });

  it('should update total price for multiple items in cart', () => {
    cy.get('[data-testid="cart-item"]').should('have.length.greaterThan', 1);

    cy.get('[data-testid="quantity-input"]').eq(0).clear().type('2');
    cy.get('[data-testid="update-quantity-btn"]').eq(0).click();

    cy.get('[data-testid="quantity-input"]').eq(1).clear().type('3');
    cy.get('[data-testid="update-quantity-btn"]').eq(1).click();

    cy.get('[data-testid="total-price"]').should(($total) => {
      const totalPrice = parseFloat($total.text().replace('$', ''));
      expect(totalPrice).to.be.greaterThan(0);
    });
  });
});
